import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    cost = [int(x) for x in data[2:2 + n]]
    p = list(range(n))
    def find(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    pos = 2 + n
    for _ in range(m):
        a = find(int(data[pos])); b = find(int(data[pos + 1]))
        pos += 2
        if a != b:
            p[a] = b
    best = {}
    for i in range(n):
        r = find(i)
        if r not in best or cost[i] < best[r]:
            best[r] = cost[i]
    print(sum(best.values()))

main()

