    def fmt(n, cost, edges):
        return f"{n} {len(edges)}\n" + ' '.join(map(str, cost)) + ('\n' if edges else '') + '\n'.join(f'{a} {b}' for a, b in edges)
    tests = [fmt(1, [5], []), fmt(2, [3, 4], []), fmt(2, [3, 4], [(0, 1)]), fmt(3, [9, 1, 9], [(0, 1), (1, 2), (0, 2)]),
             fmt(4, [4, 3, 2, 1], [(0, 0), (1, 1)]), fmt(5, [5, 4, 3, 2, 1], [(0, 1), (0, 1), (1, 0)])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(3):
            m = rng.randint(0, n)
            edges = [(rng.randrange(n), rng.randrange(n)) for _ in range(m)]
            tests.append(fmt(n, [rng.randint(1, 50) for _ in range(n)], edges))
    n = 100000
    tests.append(fmt(n, [rng.randint(1, 10**9) for _ in range(n)], []))
    tests.append(fmt(n, [rng.randint(1, 10**9) for _ in range(n)], [(i, i + 1) for i in range(n - 1)]))
    tests.append(fmt(n, [rng.randint(1, 10**9) for _ in range(n)], [(rng.randrange(n), rng.randrange(n)) for _ in range(60000)]))
    tests.append(fmt(n, [rng.randint(1, 10**9) for _ in range(n)], [(rng.randrange(n), rng.randrange(n)) for _ in range(200000)]))
    return tests

